int main(void) {
    int age = 36;
    double height = 1.7;
    char grade = 'A';

    printf("Age: %d, Height: %.1f, Grade: %c\n", age, height, grade);
    return 0;
}

#include <stdio.h>

int main(void) {
    printf("char:  %zu\n", sizeof(char));
    printf("int:   %zu\n", sizeof(int));
    printf("long:  %zu\n", sizeof(long));
    printf("double:%zu\n", sizeof(double));
    return 0;
}

