#include <stdio.h>

#define SQUARE(x) ((x) * (x))

int main(void) {
    FILE* out = fopen("data.txt", "w");
    fprintf(out, "hello\nworld\n");
    fclose(out);

    char line[64];
    FILE* in = fopen("data.txt", "r");
    while (fgets(line, sizeof(line), in)) {
        printf("%s", line);
    }
    fclose(in);

    printf("SQUARE(5) = %d\n", SQUARE(5));
    return 0;
}

#include <stdio.h>

#define BAD_SQUARE(x) x * x
#define GOOD_SQUARE(x) ((x) * (x))

int main(void) {
    printf("%d\n", 100 / BAD_SQUARE(2));  // expands to 100 / 2 * 2 = 100
    printf("%d\n", 100 / GOOD_SQUARE(2)); // expands to 100 / (2 * 2) = 25
    return 0;
}

